import pandas as pd
import numpy as np

# Load data
csv_path = Path('/app/benchmark/data.csv')
df = pd.read_csv(csv_path)

# Types
for col in ['price_pence']:
    df[col] = pd.to_numeric(df[col], errors='coerce')
df['recorded_at'] = pd.to_datetime(df['recorded_at'], utc=True, errors='coerce')
df['source_updated_at'] = pd.to_datetime(df['source_updated_at'], utc=True, errors='coerce')

# Derived
lag_hours = (df['recorded_at'] - df['source_updated_at']).dt.total_seconds() / 3600
neg_lag_count = int((lag_hours < 0).sum())
df['lag_hours_clipped'] = lag_hours.clip(lower=0)

# Basic coverage
n_records = int(len(df))
n_stations = int(df['node_id'].nunique())
fuel_types = sorted(df['fuel_type'].dropna().unique().tolist())

recorded_min = df['recorded_at'].min()
recorded_max = df['recorded_at'].max()
source_min = df['source_updated_at'].min()
source_max = df['source_updated_at'].max()

nulls = df[['id','node_id','fuel_type','price_pence','recorded_at','source_updated_at']].isna().sum().to_dict()

# Price stats
summary = df.groupby('fuel_type')['price_pence'].agg(count='count', mean='mean', median='median', min='min', max='max', std='std')
summary['q1'] = df.groupby('fuel_type')['price_pence'].quantile(0.25)
summary['q3'] = df.groupby('fuel_type')['price_pence'].quantile(0.75)
summary['iqr'] = summary['q3'] - summary['q1']
summary['spread'] = summary['max'] - summary['min']
summary = summary.loc[summary['median'].sort_values().index]

# Outlier diagnostics
outlier_rows=[]
for fuel,g in df.groupby('fuel_type'):
    q1=g['price_pence'].quantile(0.25)
    q3=g['price_pence'].quantile(0.75)
    iqr=q3-q1
    lo=q1-1.5*iqr
    hi=q3+1.5*iqr
    share=float(((g['price_pence']<lo)|(g['price_pence']>hi)).mean())
    outlier_rows.append((fuel,share,lo,hi,int(((g['price_pence']<lo)|(g['price_pence']>hi)).sum())))
outlier_df=pd.DataFrame(outlier_rows, columns=['fuel_type','outlier_share','iqr_lo','iqr_hi','outlier_count']).set_index('fuel_type').loc[summary.index]

# Freshness stats
lag = df['lag_hours_clipped']
freshness = {
    'median_hours': float(lag.median()),
    'mean_hours': float(lag.mean()),
    'p90_hours': float(lag.quantile(0.9)),
    'p95_hours': float(lag.quantile(0.95)),
    'p99_hours': float(lag.quantile(0.99)),
    'max_hours': float(lag.max()),
}
stale_props = {24: float((lag>24).mean()), 72: float((lag>72).mean()), 168: float((lag>168).mean())}

# Stations with stale patterns
station_stale_72 = df.groupby('node_id')['lag_hours_clipped'].apply(lambda s: float((s>72).mean()))
num_stations_majority_stale_72 = int((station_stale_72>0.5).sum())

# Coverage availability
fuel_types_per_station = df.groupby('node_id')['fuel_type'].nunique()
types_per_station_counts = fuel_types_per_station.value_counts().sort_index()
stations_per_fuel = df.groupby('fuel_type')['node_id'].nunique().sort_values(ascending=False)

# Helper formatters

def fmt_dt(ts):
    if pd.isna(ts):
        return 'NA'
    return ts.strftime('%Y-%m-%d %H:%M:%S UTC')

def fmt_num(x, nd=2):
    if pd.isna(x):
        return 'NA'
    return f"{x:,.{nd}f}"

def fmt_int(x):
    if pd.isna(x):
        return 'NA'
    return f"{int(x):,d}"

