img_paths = {
    'price_box': Path('/app/output/price_box.png'),
    'spread_bar': Path('/app/output/spread_bar.png'),
    'lag_hist': Path('/app/output/lag_hist.png'),
    'lag_box': Path('/app/output/lag_box.png'),
    'lag_time': Path('/app/output/lag_time.png'),
}
imgs = {}
for k,p in img_paths.items():
    b64 = base64.b64encode(p.read_bytes()).decode('ascii')
    imgs[k] = f"data:image/png;base64,{b64}"

