    float_cols = float_cols or []
    d = dfx.copy()
    for c in d.columns:
        if c in float_cols:
            d[c] = d[c].map(lambda v: fmt_num(v, 2) if pd.notna(v) else 'NA')
        elif np.issubdtype(d[c].dtype, np.number):
            # default: 2dp
            d[c] = d[c].map(lambda v: fmt_num(v, 2) if pd.notna(v) else 'NA')
    return d.to_html(index=True, escape=True, classes='table', border=0)

# Compose price summary table
