    ('95th percentile lag', f"{freshness['p95_hours']:.2f} hours"),
    ('99th percentile lag', f"{freshness['p99_hours']:.2f} hours"),
    ('Max lag (observed)', f"{freshness['max_hours']:.2f} hours"),
    ('Records with negative lag', f"{neg_lag_count:,d} (treated as 0 for lag KPIs)"),
]
for thresh, prop in stale_props.items():
    fresh_rows.append((f"Share with lag > {thresh}h", f"{prop*100:.2f}%"))

freshness_html = pd.DataFrame(fresh_rows, columns=['Metric','Value']).to_html(index=False, classes='table', border=0)

# Outliers note
