least_fuel = summary['median'].idxmin()
most_fuel = summary['median'].idxmax()
least_median = float(summary.loc[least_fuel, 'median'])
most_median = float(summary.loc[most_fuel, 'median'])
median_gap = most_median - least_median

# Spread drivers: highlight fuels with large IQR and large max-min
largest_iqr_fuel = summary['iqr'].idxmax()
largest_spread_fuel = summary['spread'].idxmax()

key_findings = [
    f"Median prices vary substantially by fuel type: {least_fuel} is lowest (median {least_median:.2f} ppl) while {most_fuel} is highest (median {most_median:.2f} ppl), a median gap of {median_gap:.2f} ppl.",
    f"Within-fuel dispersion is material: {largest_iqr_fuel} has the widest typical price band (IQR {summary.loc[largest_iqr_fuel,'iqr']:.2f} ppl). The widest overall max–min range is in {largest_spread_fuel} ({summary.loc[largest_spread_fuel,'spread']:.2f} ppl), indicating large headline disparities driven by outliers and/or data quality issues.",
